package com.railway.filter;import jakarta.servlet.*;import jakarta.servlet.http.*;import java.io.IOException;public class EncodingFilter implements Filter{public void doFilter(ServletRequest r,ServletResponse s,FilterChain c)throws IOException,ServletException{r.setCharacterEncoding("UTF-8");s.setCharacterEncoding("UTF-8");if(s instanceof HttpServletResponse h){h.setHeader("X-Content-Type-Options","nosniff");h.setHeader("X-Frame-Options","DENY");h.setHeader("Referrer-Policy","same-origin");}c.doFilter(r,s);}}
